#include <iostream>
#include <mutex>
#include <thread>

int main() {
    std::mutex gate;
    int total = 0;
    auto work = [&] { std::lock_guard<std::mutex> lock(gate); ++total; };
    std::jthread first(work);
    std::jthread second(work);
    first.join();
    second.join();
    std::cout << total << '\n';
}
